import Image from "next/image";

type Props = {
  /** Rendered edge length in px (the source is a 512px square PNG). */
  size?: number;
  priority?: boolean;
};

/** The QYRODEV mark. The transparent PNG is generated by scripts/build-brand-assets.py. */
export default function LogoMark({ size = 30, priority = false }: Props) {
  return (
    <Image
      src="/logo-mark.png"
      alt=""
      width={size}
      height={size}
      priority={priority}
      className="shrink-0 object-contain"
      style={{ width: size, height: size }}
    />
  );
}
